using ClaxeDesktop.Core;
using ClaxeDesktop.Platform.Win;
using System.Text.Json;

if (Environment.GetEnvironmentVariable("CLAXE_LAUNCH_PROBE") is { } probe)
{ await File.WriteAllTextAsync(probe, "Launch successful"); return 0; }

var tests = new List<(string Name, Func<Task> Run)>();
void Test(string name, Action action) => tests.Add((name, () => { action(); return Task.CompletedTask; }));
void Check(bool condition, string message = "Assertion failed") { if (!condition) throw new Exception(message); }
void Throws(Action action) { try { action(); } catch (InvalidDataException) { return; } throw new Exception("Expected validation failure"); }
var root = Path.Combine(Path.GetTempPath(), "ClaxeTests-" + Guid.NewGuid().ToString("N"));
Directory.CreateDirectory(root);
var screens = new[] { new MonitorInfo("left", "Left", -1920, 0, 1920, 1040, 1, false), new MonitorInfo("main", "Main", 0, 0, 2560, 1400, 1.5, true) };
Test("Default settings validate", () => new Settings().Validate());
Test("Dock edge validation", () => Throws(() => (new Settings { DockEdge = "invalid" }).Validate()));
Test("Window filter excludes hidden tools and owned popups", () => {
    var normal = new WindowCandidate(true, false, false, false, false, false, false, "App");
    Check(WindowFilter.Include(normal));
    foreach (var excluded in new[] { normal with { Visible = false }, normal with { Cloaked = true }, normal with { ToolWindow = true }, normal with { Owned = true }, normal with { OwnProcess = true }, normal with { NoActivate = true }, normal with { Title = "" } }) Check(!WindowFilter.Include(excluded));
    Check(WindowFilter.Include(normal with { Owned = true, AppWindow = true }));
});
Test("Ten windows group by case insensitive executable", () => { var list = Enumerable.Range(1, 10).Select(i => new AppWindow(i, (uint)i, "Test", i % 2 == 0 ? @"C:\Apps\TEST.exe" : @"c:\apps\test.exe", false)).ToList(); Check(WindowGrouping.Build(list, true).Count == 1); Check(WindowGrouping.Build(list, false).Count == 10); });
Test("Unknown process identity does not merge unrelated apps", () => Check(WindowGrouping.Build(new[] { new AppWindow(1, 1, "A", null, false), new AppWindow(2, 2, "B", null, false) }, true).Count == 2));
Test("Hosted UWP windows are not incorrectly merged", () => Check(WindowGrouping.Build(new[] { new AppWindow(1, 1, "A", @"C:\Windows\System32\ApplicationFrameHost.exe", false), new AppWindow(2, 1, "B", @"C:\Windows\System32\ApplicationFrameHost.exe", false) }, true).Count == 2));
Test("Group click cycles and tolerates closed previous window", () => { var list = new[] { new AppWindow(1, 1, "A", null, false), new AppWindow(2, 1, "B", null, true) }; Check(WindowGrouping.Next(list, 1)?.Handle == 2); Check(WindowGrouping.Next(list, 2)?.Handle == 1); Check(WindowGrouping.Next(list, 99)?.Handle == 1); Check(WindowGrouping.Next([], 0) is null); });
Test("Auto hide protects pointer keyboard menus and dragging", () => {
    var delay = TimeSpan.FromSeconds(1);
    Check(DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "floating", false, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", true, false, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, true, false, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, true, false, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, true, delay));
    Check(!DockVisibilityPolicy.Collapse(true, "bottom", false, false, false, false, TimeSpan.FromMilliseconds(200)));
});
Test("Closed native window activation fails gracefully", () => Check(!new WindowsWindowService().Activate(new(0, 0, "Closed", null, false))));
Test("Out-of-range appearance rejected", () => Throws(() => (new Settings { Opacity = .1 }).Validate()));
Test("Non-finite opacity rejected", () => Throws(() => (new Settings { Opacity = double.NaN }).Validate()));
Test("Invalid layout rejected", () => Throws(() => (new Settings { Panel = new("main", double.PositiveInfinity, 2) }).Validate()));
Test("Unsupported schema rejected", () => Throws(() => (new Settings { SchemaVersion = 99 }).Validate()));
Test("Remote and command launch blocked", () => { Check(!LaunchPolicy.IsAllowed("https://example.com")); Check(!LaunchPolicy.IsAllowed(@"\\server\file.exe")); Check(!LaunchPolicy.IsAllowed(@"C:\temp\run.cmd")); Check(!LaunchPolicy.IsAllowed("calc.exe")); });
Test("Local executable and shortcut accepted", () => { Check(LaunchPolicy.IsAllowed(@"C:\Windows\notepad.exe")); Check(LaunchPolicy.IsAllowed(@"C:\Apps\test.LNK")); });
Test("Null shortcut collection rejected", () => Throws(() => (new Settings { Shortcuts = null! }).Validate()));
Test("Monitor remap retains stored identity", () => { var saved = new Placement("missing", 200, 200); var result = LayoutEngine.Resolve(saved, screens, 300, 200, 0, 0, false); Check(result.Monitor.Id == "main"); Check(saved.MonitorId == "missing"); });
Test("Negative-origin screen chosen by identity", () => Check(LayoutEngine.Resolve(new("left", 100, 200), screens, 300, 200, 0, 0, false).Monitor.X == -1920));
Test("DPI clamp keeps panel in work area", () => { var p = LayoutEngine.Resolve(new("main", 9999, 9999), screens, 300, 200, 0, 0, false); Check(Math.Abs(p.X - (2560 / 1.5 - 300)) < .01); Check(p.Y <= 1400 / 1.5 - 200); });
